    const Line *x = (const Line *)pa;
    const Line *y = (const Line *)pb;
    long long dx = x->a - 1;
    long long dy = y->a - 1;

    if (dx == 0 && dy != 0) return -1;
    if (dx != 0 && dy == 0) return 1;
