        meal_a = a * meal_a % MOD;
        meal_b = (a * meal_b + b) % MOD;
    }

    int Q;
    scanf("%d", &Q);
    for (int i = 0; i < Q; i++) {
        long long x;
        scanf("%lld", &x);
        long long spell_result = solve_spells(x, K);
        long long answer = (meal_a * spell_result + meal_b) % MOD;
        printf("%lld\n", answer);
    }

    free(spell_a);
    free(spell_b);
    free(meals);
    free(hull);
    return 0;
}
